import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load textures via context
  const imageTexture = ctx.textureLoader.load(
    config.imageUrl || '/prism-mock/home/nodes/parallax-stack.png'
  );
  const depthTexture = ctx.textureLoader.load(
    config.depthMapUrl || '/prism-mock/home/nodes/parallax-stack.depth.png'
  );

  // Create tessellated plane geometry: 64x64 segments for displacement
  const geometry = new THREE.PlaneGeometry(2, 1.25, 64, 64);

  // Material with displacement mapping from depth texture
  const material = new THREE.MeshStandardMaterial({
    map: imageTexture,
    displacementMap: depthTexture,
    displacementScale: 0.1,
    metalness: 0.2,
    roughness: 0.6,
  });

  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene placement
  const position = config.position || { x: -1.25, y: 1.6, z: 0 };
  mesh.position.set(position.x, position.y, position.z);

  if (config.rotation) {
    mesh.rotation.fromArray(config.rotation);
  }

  const scale = config.scale || { x: 1, y: 1, z: 1 };
  mesh.scale.set(scale.x, scale.y, scale.z);

  group.add(mesh);

  // Preserve original transforms for animation resets
  const originalPosition = mesh.position.clone();
  const originalRotation = mesh.rotation.clone();
  const originalScale = mesh.scale.clone();

  let isHovering = false;

  // Event handlers stored in userData for framework integration
  group.userData.handlers = {
    hover: () => {
      isHovering = true;
      // Rise-in preset: y +0.15, power3.out, 0.7s
      gsap.to(mesh.position, {
        y: originalPosition.y + 0.15,
        duration: 0.7,
        ease: 'power3.out',
        overwrite: 'auto'
      });
    },

    hoverOut: () => {
      isHovering = false;
      gsap.to(mesh.position, {
        y: originalPosition.y,
        duration: 0.5,
        ease: 'power2.out',
        overwrite: 'auto'
      });
      gsap.to(mesh.rotation, {
        x: originalRotation.x,
        y: originalRotation.y,
        duration: 0.6,
        ease: 'power2.out',
        overwrite: 'auto'
      });
    },

    pointerMove: (event) => {
      if (!isHovering) return;

      const rect = event.target?.getBoundingClientRect();
      if (!rect) return;

      // Parallax effect: rotate based on cursor position
      const normalizedX = (event.clientX - rect.left) / rect.width;
      const normalizedY = (event.clientY - rect.top) / rect.height;

      gsap.to(mesh.rotation, {
        y: (normalizedX - 0.5) * 0.2,
        x: (normalizedY - 0.5) * -0.2,
        duration: 0.4,
        ease: 'power2.out',
        overwrite: 'auto'
      });
    },

    pointerDown: () => {
      // Press-down effect: scale 0.97
      gsap.to(mesh.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
        overwrite: 'auto'
      });
    },

    pointerUp: () => {
      gsap.to(mesh.scale, {
        x: originalScale.x,
        y: originalScale.y,
        z: originalScale.z,
        duration: 0.1,
        ease: 'power2.out',
        overwrite: 'auto'
      });
    },

    click: () => {
      // Emit hub-features.select event
      const selectEvent = new CustomEvent('hub-features.select', {
        detail: { nodeId: config.id }
      });
      window.dispatchEvent(selectEvent);

      // Navigate via data binding (trpc.checkout.begin.checkoutUrl)
      if (config.checkoutUrl) {
        window.location.href = config.checkoutUrl;
      }
    }
  };

  // Cleanup function
  group.userData.cleanup = () => {
    gsap.killTweensOf([mesh.position, mesh.rotation, mesh.scale]);
    geometry.dispose();
    material.dispose();
    imageTexture.dispose();
    depthTexture.dispose();
  };

  return group;
}
